from jsonb_populate_recordset(null::public.drug_infusion_params, $catalog$[{"id":"pivekimab-sunirine.glucose","drug_id":"pivekimab-sunirine","solvent":"glucose_5","concentration_min_mg_ml":null,"concentration_max_mg_ml":null,"stock_concentration_mg_ml":0.2,"max_rate_mg_min":null,"duration_options":[],"min_duration_min":null,"rate_ramp":null,"ramp_sequence":null,"bag_volumes_ml":[],"duration_min":null,"is_default":true,"notes":{"uk":"Інструкція велить два розведення 5 % глюкозою: у флакон додають 4,8 мл (0,4 мг/мл), потім відібраний обʼєм змішують у шприці з рівним обʼємом 5 % глюкози — остаточно 0,2 мг/мл. Мішка немає: обʼєм введення = доза / 0,2 мг/мл, вводиться шприцевим насосом.","en":"The label prescribes two dilutions in 5% dextrose: 4.8 mL into the vial (0.4 mg/mL), then the withdrawn volume is mixed in a syringe with an equal volume of 5% dextrose, giving 0.2 mg/mL. There is no bag: the infused volume is the dose divided by 0.2 mg/mL, given by syringe pump."},"sources":[{"name":"FDA label: DECNUPAZ (pivekimab sunirine-pvzy), розділ 2.5 Instructions for Preparation","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=508b6ff8-601d-4901-a7a5-816141134054","checkedOn":"2026-11-20"}],"sort_order":0},{"id":"tagraxofusp.nacl","drug_id":"tagraxofusp","solvent":"sodium_chloride_0_9","concentration_min_mg_ml":null,"concentration_max_mg_ml":null,"stock_concentration_mg_ml":0.1,"max_rate_mg_min":null,"duration_options":[],"min_duration_min":null,"rate_ramp":null,"ramp_sequence":null,"bag_volumes_ml":[],"duration_min":15,"is_default":true,"notes":{"uk":"Інструкція велить перенести 9 мл 0,9 % натрію хлориду в порожній стерильний флакон на 10 мл і додати туди 1 мл (1000 мкг) препарату — виходить 100 мкг/мл. Мішка немає: потрібний обʼєм набирають у шприц і вводять шприцевим насосом за 15 хв, після чого систему промивають щонайменше 3 мл 0,9 % NaCl (промивання входить у ці 15 хв). Обʼєм введення = доза / 100 мкг/мл.","en":"The label says to transfer 9 mL of 0.9% sodium chloride into an empty sterile 10 mL vial and add 1 mL (1000 mcg) of the drug to it, giving 100 mcg/mL. There is no bag: the required volume is drawn into a syringe and given by syringe pump over 15 minutes, after which the line is flushed with at least 3 mL of 0.9% sodium chloride (the flush counts inside those 15 minutes). The infused volume is the dose divided by 100 mcg/mL."},"sources":[{"name":"FDA label: ELZONRIS (tagraxofusp-erzs), розділ 2.4 Preparation and Administration — 1 мл флакона в 9 мл 0,9 % NaCl до 100 мкг/мл","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=80eb1080-fe20-4af0-b2a5-a67999923fa8","checkedOn":"2026-11-20"}],"sort_order":0}]$catalog$::jsonb)
on conflict (id) do update set drug_id = excluded.drug_id, solvent = excluded.solvent, concentration_min_mg_ml = excluded.concentration_min_mg_ml, concentration_max_mg_ml = excluded.concentration_max_mg_ml, stock_concentration_mg_ml = excluded.stock_concentration_mg_ml, max_rate_mg_min = excluded.max_rate_mg_min, duration_options = excluded.duration_options, min_duration_min = excluded.min_duration_min, rate_ramp = excluded.rate_ramp, ramp_sequence = excluded.ramp_sequence, bag_volumes_ml = excluded.bag_volumes_ml, duration_min = excluded.duration_min, is_default = excluded.is_default, notes = excluded.notes, sources = excluded.sources, sort_order = excluded.sort_order;

insert into public.regimens (id, short_name, name, description, cycle_length_days, default_cycles, sort_order, sources, evidence, reference, course, print_forms)
select id, short_name, name, description, cycle_length_days, default_cycles, sort_order, sources, evidence, reference, course, print_forms
from jsonb_populate_recordset(null::public.regimens, $catalog$[{"id":"clad-ldac-consolidation","short_name":"Clad/LDAC, консолідація A","name":{"uk":"Кладрибін + малі дози цитарабіну, консолідація (цикл A)","en":"Cladribine with low-dose cytarabine, consolidation (cycle A)"},"description":{"uk":"Після ремісії: два цикли A чергуються з двома циклами децитабіну (B), до 18 циклів.","en":"After remission: two A cycles alternate with two decitabine cycles (B), up to 18 cycles."},"cycle_length_days":28,"default_cycles":2,"sort_order":0,"sources":[{"name":"Kadia T.M. та ін. Cladribine and low-dose cytarabine alternating with decitabine as front-line therapy for elderly patients with acute myeloid leukaemia: a phase 2 single-arm trial. Lancet Haematol. 2018;5(9):e411-e421","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6775639/","version":"рукопис автора в PMC, розділ Procedures","checkedOn":"2026-10-09"},{"name":"EMC SmPC: Leustat injection (cladribine 1 mg/ml), розділи 4.2, 6.6 — розведення в 100–500 мл 0,9 % NaCl","url":"https://www.medicines.org.uk/emc/product/13187/smpc","version":"Date of revision of the text 23/04/2026","checkedOn":"2026-11-20"}],"evidence":{"design":{"uk":"Одноцентрове дослідження фази II (MD Anderson) без групи порівняння. Два 28-денні цикли кладрибіну з малими дозами цитарабіну чергуються з двома циклами децитабіну, до 18 циклів. Цикли кожні 4–7 тижнів залежно від відновлення крові (нейтрофіли ≥1×10⁹/л, тромбоцити ≥50×10⁹/л).","en":"A single-centre phase II study (MD Anderson) without a comparison group. Two 28-day cycles of cladribine with low-dose cytarabine alternate with two cycles of decitabine, up to 18 cycles. Cycles every 4 to 7 weeks depending on count recovery (neutrophils ≥1×10⁹/L, platelets ≥50×10⁹/L)."},"population":{"uk":"118 пацієнтів від 60 років (медіана 69, 44% від 70) з нелікованим ГМЛ або МДС високого ризику, ECOG ≤2. 41% — несприятливий каріотип, 17% — мутація TP53.","en":"118 patients aged 60 or over (median 69, 44% 70 or over) with untreated AML or high-risk MDS, ECOG 2 or less. 41% adverse karyotype, 17% TP53 mutation."},"results":{"uk":"Повна ремісія 58%, з неповним відновленням ще 9% (разом 68%). Медіана безрецидивної виживаності 10,8 місяця, загальної — 13,8 місяця.","en":"Complete remission 58%, with incomplete recovery a further 9% (68% in all). Median disease-free survival 10.8 months, overall 13.8 months."},"conduct":{"uk":"Смертність за 4 тижні 1%, за 8 тижнів 7%. Негематологічні побічні дії 3+ ступеня: інфекції 75%, підвищення білірубіну 22%, висип 11%, нудота 11%. Цитарабін вводять через 3–6 годин після початку інфузії кладрибіну. Якщо після циклу 1 немає ремісії — можна повторити індукцію.","en":"Four-week mortality 1%, eight-week 7%. Grade 3+ non-haematological adverse events: infection 75%, raised bilirubin 22%, rash 11%, nausea 11%. Cytarabine is given 3 to 6 hours after the start of the cladribine infusion. Without remission after cycle 1, induction may be repeated."},"trial":{"nct":"NCT01515527","phase":"II","randomized":false,"n":118},"settings":["first-line","elderly"],"verdict":"option","appraisal":[{"publication":"Kadia T.M. та ін. Lancet Haematol. 2018;5(9):e411-e421","pmid":"30115541","level":{"scale":"oxford-cebm-2011","value":"4","notes":{"uk":"Дослідження без рандомізованої групи порівняння: усі пацієнти отримували ту саму схему. За оксфордською шкалою це 4-й рівень.","en":"A study without a randomised comparison group: every patient had the same regimen. That is level 4 on the Oxford scale."}},"publication_types":["Clinical Trial, Phase II","Journal Article"],"journal":{"name":"The Lancet Haematology","issn":"2352-3026","medline_indexed":true},"sources":[{"name":"Запис статті в PubMed (типи публікації за класифікацією NLM)","url":"https://pubmed.ncbi.nlm.nih.gov/30115541/","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Каталог NLM, запис журналу «The Lancet Haematology» (статус індексації)","url":"https://www.ncbi.nlm.nih.gov/nlmcatalog/101643584","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Oxford Centre for Evidence-Based Medicine, рівні доказовості 2011","url":"https://www.cebm.ox.ac.uk/resources/levels-of-evidence/ocebm-levels-of-evidence","version":"редакція 2011 року","checkedOn":"2026-10-09"}]}]},"reference":null,"course":{"id":"clad-ldac","title":{"uk":"Кладрибін + LDAC","en":"Cladribine + LDAC"},"phase":{"uk":"консолідація A","en":"consolidation A"},"order":2,"cycles":null},"print_forms":{"version":1,"forms":[]}},{"id":"clad-ldac-induction","short_name":"Clad/LDAC, індукція","name":{"uk":"Кладрибін + малі дози цитарабіну, індукція (з чергуванням з децитабіном)","en":"Cladribine with low-dose cytarabine, induction (alternating with decitabine)"},"description":{"uk":"Літні (від 60 років) з уперше діагностованим ГМЛ, яким підходить терапія низької інтенсивності. Цикл 28 днів; без ремісії — можна повторити.","en":"Elderly patients (60 or over) with newly diagnosed AML suited to low-intensity therapy. A 28-day cycle; without remission it may be repeated."},"cycle_length_days":28,"default_cycles":1,"sort_order":0,"sources":[{"name":"Kadia T.M. та ін. Cladribine and low-dose cytarabine alternating with decitabine as front-line therapy for elderly patients with acute myeloid leukaemia: a phase 2 single-arm trial. Lancet Haematol. 2018;5(9):e411-e421","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6775639/","version":"рукопис автора в PMC, розділ Procedures","checkedOn":"2026-10-09"},{"name":"EMC SmPC: Leustat injection (cladribine 1 mg/ml), розділи 4.2, 6.6 — розведення в 100–500 мл 0,9 % NaCl","url":"https://www.medicines.org.uk/emc/product/13187/smpc","version":"Date of revision of the text 23/04/2026","checkedOn":"2026-11-20"}],"evidence":{"design":{"uk":"Одноцентрове дослідження фази II (MD Anderson) без групи порівняння. Два 28-денні цикли кладрибіну з малими дозами цитарабіну чергуються з двома циклами децитабіну, до 18 циклів. Цикли кожні 4–7 тижнів залежно від відновлення крові (нейтрофіли ≥1×10⁹/л, тромбоцити ≥50×10⁹/л).","en":"A single-centre phase II study (MD Anderson) without a comparison group. Two 28-day cycles of cladribine with low-dose cytarabine alternate with two cycles of decitabine, up to 18 cycles. Cycles every 4 to 7 weeks depending on count recovery (neutrophils ≥1×10⁹/L, platelets ≥50×10⁹/L)."},"population":{"uk":"118 пацієнтів від 60 років (медіана 69, 44% від 70) з нелікованим ГМЛ або МДС високого ризику, ECOG ≤2. 41% — несприятливий каріотип, 17% — мутація TP53.","en":"118 patients aged 60 or over (median 69, 44% 70 or over) with untreated AML or high-risk MDS, ECOG 2 or less. 41% adverse karyotype, 17% TP53 mutation."},"results":{"uk":"Повна ремісія 58%, з неповним відновленням ще 9% (разом 68%). Медіана безрецидивної виживаності 10,8 місяця, загальної — 13,8 місяця.","en":"Complete remission 58%, with incomplete recovery a further 9% (68% in all). Median disease-free survival 10.8 months, overall 13.8 months."},"conduct":{"uk":"Смертність за 4 тижні 1%, за 8 тижнів 7%. Негематологічні побічні дії 3+ ступеня: інфекції 75%, підвищення білірубіну 22%, висип 11%, нудота 11%. Цитарабін вводять через 3–6 годин після початку інфузії кладрибіну. Якщо після циклу 1 немає ремісії — можна повторити індукцію.","en":"Four-week mortality 1%, eight-week 7%. Grade 3+ non-haematological adverse events: infection 75%, raised bilirubin 22%, rash 11%, nausea 11%. Cytarabine is given 3 to 6 hours after the start of the cladribine infusion. Without remission after cycle 1, induction may be repeated."},"trial":{"nct":"NCT01515527","phase":"II","randomized":false,"n":118},"settings":["first-line","elderly"],"verdict":"option","appraisal":[{"publication":"Kadia T.M. та ін. Lancet Haematol. 2018;5(9):e411-e421","pmid":"30115541","level":{"scale":"oxford-cebm-2011","value":"4","notes":{"uk":"Дослідження без рандомізованої групи порівняння: усі пацієнти отримували ту саму схему. За оксфордською шкалою це 4-й рівень.","en":"A study without a randomised comparison group: every patient had the same regimen. That is level 4 on the Oxford scale."}},"publication_types":["Clinical Trial, Phase II","Journal Article"],"journal":{"name":"The Lancet Haematology","issn":"2352-3026","medline_indexed":true},"sources":[{"name":"Запис статті в PubMed (типи публікації за класифікацією NLM)","url":"https://pubmed.ncbi.nlm.nih.gov/30115541/","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Каталог NLM, запис журналу «The Lancet Haematology» (статус індексації)","url":"https://www.ncbi.nlm.nih.gov/nlmcatalog/101643584","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Oxford Centre for Evidence-Based Medicine, рівні доказовості 2011","url":"https://www.cebm.ox.ac.uk/resources/levels-of-evidence/ocebm-levels-of-evidence","version":"редакція 2011 року","checkedOn":"2026-10-09"}]}]},"reference":null,"course":{"id":"clad-ldac","title":{"uk":"Кладрибін + LDAC","en":"Cladribine + LDAC"},"phase":{"uk":"індукція","en":"induction"},"order":1,"cycles":null},"print_forms":{"version":1,"forms":[]}},{"id":"clad-ldac-ven-cons-a","short_name":"Clad/LDAC+Ven, конс. A","name":{"uk":"Кладрибін + ЦГП + венетоклакс, консолідація A","en":"Cladribine + LDAC + venetoclax, consolidation A"},"description":{"uk":"Курси консолідації 1, 4–5, 8–9, 12–13, 16–17: кладрибін 5 мг/м² д. 1–3, ЦГП 20 мг двічі на добу д. 1–10, венетоклакс 400 мг д. 1–21.","en":"Consolidation courses 1, 4-5, 8-9, 12-13, 16-17: cladribine 5 mg/m2 d1-3, LDAC 20 mg twice daily d1-10, venetoclax 400 mg d1-21."},"cycle_length_days":28,"default_cycles":9,"sort_order":0,"sources":[{"name":"NCCN Guidelines: Acute Myeloid Leukemia, AML-E 4 of 14 (дози й дні як факти; текст не копіювався)","url":"https://www.nccn.org/guidelines/guidelines-detail?category=1&id=1411","version":"5.2026 від 15.07.2026","checkedOn":"2026-10-22"},{"name":"EMC SmPC: Leustat injection (cladribine 1 mg/ml), розділи 4.2, 6.6 — розведення в 100–500 мл 0,9 % NaCl","url":"https://www.medicines.org.uk/emc/product/13187/smpc","version":"Date of revision of the text 23/04/2026","checkedOn":"2026-11-20"}],"evidence":null,"reference":null,"course":{"id":"clad-ldac-ven","title":{"uk":"Кладрибін + ЦГП + венетоклакс (NCCN)","en":"Cladribine + LDAC + venetoclax (NCCN)"},"phase":{"uk":"консолідація (курси A; B — окрема схема)","en":"consolidation (A courses; B is a separate regimen)"},"order":2,"cycles":{"from":2,"to":null}},"print_forms":{"version":1,"forms":[]}},{"id":"clad-ldac-ven-induction","short_name":"Clad/LDAC+Ven, індукція","name":{"uk":"Кладрибін + ЦГП + венетоклакс, індукція","en":"Cladribine + LDAC + venetoclax, induction"},"description":{"uk":"Непридатні до інтенсивної терапії, без IDH1 (категорія 2B): кладрибін 5 мг/м² д. 1–5, ЦГП 20 мг двічі на добу д. 1–10, венетоклакс 100/200/400 мг д. 1–21. Без CR/CRi — можна повторити індукцію.","en":"Unfit for intensive therapy, no IDH1 (category 2B): cladribine 5 mg/m2 d1-5, LDAC 20 mg twice daily d1-10, venetoclax 100/200/400 mg d1-21. Without CR/CRi the induction may be repeated."},"cycle_length_days":28,"default_cycles":1,"sort_order":0,"sources":[{"name":"NCCN Guidelines: Acute Myeloid Leukemia, AML-4, AML-E 4 of 14 (дози й дні як факти; текст не копіювався)","url":"https://www.nccn.org/guidelines/guidelines-detail?category=1&id=1411","version":"5.2026 від 15.07.2026","checkedOn":"2026-10-22"},{"name":"EMC SmPC: Leustat injection (cladribine 1 mg/ml), розділи 4.2, 6.6 — розведення в 100–500 мл 0,9 % NaCl","url":"https://www.medicines.org.uk/emc/product/13187/smpc","version":"Date of revision of the text 23/04/2026","checkedOn":"2026-11-20"}],"evidence":null,"reference":null,"course":{"id":"clad-ldac-ven","title":{"uk":"Кладрибін + ЦГП + венетоклакс (NCCN)","en":"Cladribine + LDAC + venetoclax (NCCN)"},"phase":{"uk":"індукція","en":"induction"},"order":1,"cycles":{"from":1,"to":1}},"print_forms":{"version":1,"forms":[]}},{"id":"clag-m","short_name":"CLAG-M","name":{"uk":"CLAG-M (кладрибін + цитарабін + мітоксантрон + Г-КСФ)","en":"CLAG-M (cladribine, cytarabine, mitoxantrone and G-CSF)"},"description":{"uk":"Рефрактерний або рецидивний ГМЛ. Один курс; при частковій ремісії — другий. Г-КСФ починають напередодні (день 0).","en":"Refractory or relapsed AML. One course; a second one for a partial remission. G-CSF starts the day before (day 0)."},"cycle_length_days":28,"default_cycles":1,"sort_order":0,"sources":[{"name":"Wierzbowska A. та ін. Cladribine combined with high doses of arabinoside cytosine, mitoxantrone, and G-CSF (CLAG-M) is a highly effective salvage regimen in patients with refractory and relapsed acute myeloid leukemia of the poor risk: a final report of the Polish Adult Leukemia Group. Eur J Haematol. 2008;80(2):115-126","url":"https://pubmed.ncbi.nlm.nih.gov/18076637/","version":"резюме; фаза II, 118 пацієнтів","checkedOn":"2026-10-09"},{"name":"ClinicalTrials.gov NCT03257241 (PALG: DA-90 проти DAC; порятунок CLAG-M проти FLAG-IDA), опис груп лікування","url":"https://clinicaltrials.gov/study/NCT03257241","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"EMC SmPC: Leustat injection (cladribine 1 mg/ml), розділи 4.2, 6.6 — розведення в 100–500 мл 0,9 % NaCl","url":"https://www.medicines.org.uk/emc/product/13187/smpc","version":"Date of revision of the text 23/04/2026","checkedOn":"2026-11-20"},{"name":"FDA label: Mitoxantrone Injection USP (concentrate), Dosage and Administration — розводити щонайменше до 50 мл","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=accf9569-4b57-4e83-a7db-4e890a75d1ba","checkedOn":"2026-11-20"}],"evidence":{"design":{"uk":"Багатоцентрові дослідження фази II Польської групи з лейкозів дорослих без групи порівняння. Після повної ремісії — консолідація високими дозами цитарабіну з мітоксантроном ± кладрибін.","en":"Multicentre phase II studies of the Polish Adult Leukemia Group without a comparison group. After complete remission, consolidation with high-dose cytarabine and mitoxantrone ± cladribine."},"population":{"uk":"118 пацієнтів з 11 центрів: 78 первинно резистентних і 40 з рецидивом, поганий прогноз.","en":"118 patients from 11 centres: 78 primary refractory and 40 relapsed, poor risk."},"results":{"uk":"Повна ремісія 58% після одного-двох курсів, резистентність 35%, рання смерть 7%. Чотирирічна загальна виживаність 14%, безрецидивна — 30%. Гірше при лейкоцитах понад 10×10⁹/л, віці понад 34 роки і несприятливому каріотипі. У меншому дослідженні тієї ж групи (43 пацієнти) — ремісія 49%, рання смерть 5%.","en":"Complete remission 58% after one or two courses, refractory 35%, early death 7%. Four-year overall survival 14%, disease-free 30%. Worse with leukocytes over 10×10⁹/L, age over 34 and an adverse karyotype. In a smaller study of the same group (43 patients) remission 49%, early death 5%."},"conduct":{"uk":"Найвиразніша токсичність — гематологічна. Г-КСФ з дня 0 до дня 5.","en":"The most prominent toxicity is haematological. G-CSF from day 0 to day 5."},"trial":{"acronym":"PALG CLAG-M","phase":"II","randomized":false,"n":118},"settings":["relapse","refractory","pre-transplant"],"verdict":"option","appraisal":[{"publication":"Wierzbowska A. та ін. Eur J Haematol. 2008;80(2):115-126","pmid":"18076637","level":{"scale":"oxford-cebm-2011","value":"4","notes":{"uk":"Дослідження без рандомізованої групи порівняння: усі пацієнти отримували ту саму схему. За оксфордською шкалою це 4-й рівень.","en":"A study without a randomised comparison group: every patient had the same regimen. That is level 4 on the Oxford scale."}},"publication_types":["Journal Article","Research Support, Non-U.S. Gov't"],"journal":{"name":"European Journal of Haematology","issn":"0902-4441","medline_indexed":true},"sources":[{"name":"Запис статті в PubMed (типи публікації за класифікацією NLM)","url":"https://pubmed.ncbi.nlm.nih.gov/18076637/","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Каталог NLM, запис журналу «European Journal of Haematology» (статус індексації)","url":"https://www.ncbi.nlm.nih.gov/nlmcatalog/8703985","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Oxford Centre for Evidence-Based Medicine, рівні доказовості 2011","url":"https://www.cebm.ox.ac.uk/resources/levels-of-evidence/ocebm-levels-of-evidence","version":"редакція 2011 року","checkedOn":"2026-10-09"}]},{"publication":"Wrzesień-Kuś A. та ін. Ann Hematol. 2005;84(9):557-564","pmid":"15856358","level":{"scale":"oxford-cebm-2011","value":"4","notes":{"uk":"Дослідження без рандомізованої групи порівняння: усі пацієнти отримували ту саму схему. За оксфордською шкалою це 4-й рівень.","en":"A study without a randomised comparison group: every patient had the same regimen. That is level 4 on the Oxford scale."}},"publication_types":["Clinical Trial","Clinical Trial, Phase II","Journal Article","Multicenter Study"],"journal":{"name":"Annals of Hematology","issn":"0939-5555","medline_indexed":true},"sources":[{"name":"Запис статті в PubMed (типи публікації за класифікацією NLM)","url":"https://pubmed.ncbi.nlm.nih.gov/15856358/","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Каталог NLM, запис журналу «Annals of Hematology» (статус індексації)","url":"https://www.ncbi.nlm.nih.gov/nlmcatalog/9107334","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Oxford Centre for Evidence-Based Medicine, рівні доказовості 2011","url":"https://www.cebm.ox.ac.uk/resources/levels-of-evidence/ocebm-levels-of-evidence","version":"редакція 2011 року","checkedOn":"2026-10-09"}]}]},"reference":null,"course":null,"print_forms":{"version":1,"forms":[]}},{"id":"clia-relapse","short_name":"CLIA (рецидив)","name":{"uk":"CLIA (кладрибін + ідарубіцин + цитарабін), рецидив або рефрактерність","en":"CLIA (cladribine, idarubicin, cytarabine), relapse or refractory disease"},"description":{"uk":"Рецидивний або рефрактерний ГМЛ, переважно як міст до алогенної трансплантації. Один курс індукції.","en":"Relapsed or refractory AML, mostly as a bridge to an allogeneic transplant. One induction course."},"cycle_length_days":28,"default_cycles":1,"sort_order":0,"sources":[{"name":"Goulart H. та ін. Cladribine, idarubicin, and cytarabine (CLIA) for patients with relapsed and/or refractory acute myeloid leukemia: A single-center, single-arm, phase 2 trial. Cancer. 2025;131(8):e35840","url":"https://pubmed.ncbi.nlm.nih.gov/40193193/","version":"резюме","checkedOn":"2026-10-09"},{"name":"Kadia T.M. та ін. Venetoclax plus intensive chemotherapy with cladribine, idarubicin, and cytarabine in patients with newly diagnosed acute myeloid leukaemia or high-risk myelodysplastic syndrome: a cohort from a single-centre, single-arm, phase 2 trial. Lancet Haematol. 2021;8(8):e552-e561","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8884174/","version":"рукопис автора в PMC, розділ Procedures","checkedOn":"2026-10-09"},{"name":"EMC SmPC: Leustat injection (cladribine 1 mg/ml), розділи 4.2, 6.6 — розведення в 100–500 мл 0,9 % NaCl","url":"https://www.medicines.org.uk/emc/product/13187/smpc","version":"Date of revision of the text 23/04/2026","checkedOn":"2026-11-20"},{"name":"EMC SmPC: Zavedos 1mg/mL Solution for Injection, розділ 6.6 — у систему з вільно текучим 0,9 % NaCl, обʼєм не вказано","url":"https://www.medicines.org.uk/emc/product/13262/smpc","checkedOn":"2026-11-20"}],"evidence":{"design":{"uk":"Одноцентрове дослідження фази II (MD Anderson) без групи порівняння; при мутації FLT3 додавали сорафеніб.","en":"A single-centre phase II study (MD Anderson) without a comparison group; sorafenib was added for FLT3 mutations."},"population":{"uk":"Рецидивний або рефрактерний ГМЛ; 35 пацієнтів у першому порятунку.","en":"Relapsed or refractory AML; 35 patients in first salvage."},"results":{"uk":"Композитна повна ремісія 33%, у першому порятунку 49%. Медіана загальної виживаності 7,9 місяця (у першому порятунку 12). Після трансплантації — 78 місяців проти 8,8 без неї.","en":"Composite complete remission 33%, 49% in first salvage. Median overall survival 7.9 months (12 in first salvage). After a transplant 78 months against 8.8 without."},"conduct":{"uk":"Смертність за 4 і 8 тижнів — 6% і 17%. Побічні дії 3+ ступеня — переважно інфекції й підвищення печінкових ферментів.","en":"Four- and eight-week mortality 6% and 17%. Grade 3+ adverse events were mostly infections and raised liver enzymes."},"trial":{"nct":"NCT02115295","phase":"II","randomized":false},"settings":["relapse","refractory","pre-transplant"],"verdict":"option","appraisal":[{"publication":"Goulart H. та ін. Cancer. 2025;131(8):e35840","pmid":"40193193","level":{"scale":"oxford-cebm-2011","value":"4","notes":{"uk":"Дослідження без рандомізованої групи порівняння: усі пацієнти отримували ту саму схему. За оксфордською шкалою це 4-й рівень.","en":"A study without a randomised comparison group: every patient had the same regimen. That is level 4 on the Oxford scale."}},"publication_types":["Journal Article","Clinical Trial, Phase II"],"journal":{"name":"Cancer","issn":"0008-543X","medline_indexed":true},"sources":[{"name":"Запис статті в PubMed (типи публікації за класифікацією NLM)","url":"https://pubmed.ncbi.nlm.nih.gov/40193193/","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Каталог NLM, запис журналу «Cancer» (статус індексації)","url":"https://www.ncbi.nlm.nih.gov/nlmcatalog/0374236","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Oxford Centre for Evidence-Based Medicine, рівні доказовості 2011","url":"https://www.cebm.ox.ac.uk/resources/levels-of-evidence/ocebm-levels-of-evidence","version":"редакція 2011 року","checkedOn":"2026-10-09"}]}]},"reference":null,"course":null,"print_forms":{"version":1,"forms":[]}},{"id":"clia-ven-consolidation","short_name":"CLIA-Ven, консолідація","name":{"uk":"CLIA + венетоклакс, консолідація","en":"CLIA plus venetoclax, consolidation"},"description":{"uk":"Після ремісії: курси по 28 днів, разом з індукцією до 6 курсів, або алогенна трансплантація.","en":"After remission: 28-day courses, up to 6 including induction, or an allogeneic transplant."},"cycle_length_days":28,"default_cycles":5,"sort_order":0,"sources":[{"name":"Kadia T.M. та ін. Venetoclax plus intensive chemotherapy with cladribine, idarubicin, and cytarabine in patients with newly diagnosed acute myeloid leukaemia or high-risk myelodysplastic syndrome: a cohort from a single-centre, single-arm, phase 2 trial. Lancet Haematol. 2021;8(8):e552-e561","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8884174/","version":"рукопис автора в PMC, розділ Procedures","checkedOn":"2026-10-09"},{"name":"EMC SmPC: Leustat injection (cladribine 1 mg/ml), розділи 4.2, 6.6 — розведення в 100–500 мл 0,9 % NaCl","url":"https://www.medicines.org.uk/emc/product/13187/smpc","version":"Date of revision of the text 23/04/2026","checkedOn":"2026-11-20"},{"name":"EMC SmPC: Zavedos 1mg/mL Solution for Injection, розділ 6.6 — у систему з вільно текучим 0,9 % NaCl, обʼєм не вказано","url":"https://www.medicines.org.uk/emc/product/13262/smpc","checkedOn":"2026-11-20"}],"evidence":{"design":{"uk":"Одноцентрове дослідження фази II (MD Anderson) без групи порівняння, окрема когорта з венетоклаксом. Курси по 28 днів, до 6 курсів; у першій ремісії — алогенна трансплантація, якщо можлива.","en":"A single-centre phase II study (MD Anderson) without a comparison group, a separate venetoclax cohort. 28-day courses, up to 6; an allogeneic transplant in first remission where possible."},"population":{"uk":"50 пацієнтів 18–65 років (медіана 48) з уперше діагностованим ГМЛ, змішаним фенотипом або МДС високого ризику.","en":"50 patients aged 18 to 65 (median 48) with newly diagnosed AML, mixed phenotype or high-risk MDS."},"results":{"uk":"Композитна повна ремісія 94%, МЗХ не виявлена у 82%. Річна виживаність без подій 68%, загальна — 85%. Одна смерть під час індукції.","en":"Composite complete remission 94%, undetectable MRD in 82%. One-year event-free survival 68%, overall 85%. One induction death."},"conduct":{"uk":"Перший курс — у стаціонарі. Венетоклакс 400 мг у дні 2–8 без нарощування; при лейкоцитах понад 20×10⁹/л — циторедукція до початку. З азолами: сильні інгібітори CYP3A — венетоклакс 100 мг, помірні — 200 мг. Антибактеріальна, противірусна і протигрибкова профілактика на час нейтропенії. Фебрильна нейтропенія 3+ ступеня у 84%, підвищення АЛТ. При мутації FLT3 у дослідженні додавали мідостаурин (в Україні недоступний) або гілтеритиніб (є у відділенні); дозування в поєднанні з CLIA тут не звірене.","en":"The first course is inpatient. Venetoclax 400 mg on days 2 to 8 without a ramp-up; with leukocytes over 20×10⁹/L, cytoreduction first. With azoles: strong CYP3A inhibitors, venetoclax 100 mg; moderate, 200 mg. Antibacterial, antiviral and antifungal prophylaxis during neutropenia. Grade 3+ febrile neutropenia in 84%, raised ALT. With an FLT3 mutation the study added midostaurin (not available in Ukraine) or gilteritinib (available in the department); its dosing with CLIA is not checked here."},"trial":{"nct":"NCT02115295","phase":"II","randomized":false,"n":50},"settings":["first-line","high-risk"],"verdict":"option","appraisal":[{"publication":"Kadia T.M. та ін. Lancet Haematol. 2021;8(8):e552-e561","pmid":"34329576","level":{"scale":"oxford-cebm-2011","value":"4","notes":{"uk":"Дослідження без рандомізованої групи порівняння: усі пацієнти отримували ту саму схему. За оксфордською шкалою це 4-й рівень.","en":"A study without a randomised comparison group: every patient had the same regimen. That is level 4 on the Oxford scale."}},"publication_types":["Clinical Trial, Phase II","Journal Article"],"journal":{"name":"The Lancet Haematology","issn":"2352-3026","medline_indexed":true},"sources":[{"name":"Запис статті в PubMed (типи публікації за класифікацією NLM)","url":"https://pubmed.ncbi.nlm.nih.gov/34329576/","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Каталог NLM, запис журналу «The Lancet Haematology» (статус індексації)","url":"https://www.ncbi.nlm.nih.gov/nlmcatalog/101643584","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Oxford Centre for Evidence-Based Medicine, рівні доказовості 2011","url":"https://www.cebm.ox.ac.uk/resources/levels-of-evidence/ocebm-levels-of-evidence","version":"редакція 2011 року","checkedOn":"2026-10-09"}]}]},"reference":null,"course":{"id":"clia-ven","title":{"uk":"CLIA-Ven","en":"CLIA-Ven"},"phase":{"uk":"консолідація","en":"consolidation"},"order":2,"cycles":null},"print_forms":{"version":1,"forms":[]}},{"id":"clia-ven-induction","short_name":"CLIA-Ven, індукція","name":{"uk":"CLIA + венетоклакс (кладрибін, ідарубіцин, цитарабін), індукція","en":"CLIA plus venetoclax (cladribine, idarubicin, cytarabine), induction"},"description":{"uk":"Вперше діагностований ГМЛ або МДС високого ризику, вік 18–65, придатні до інтенсивної терапії. Курс 28 днів, у стаціонарі.","en":"Newly diagnosed AML or high-risk MDS, age 18 to 65, fit for intensive therapy. A 28-day course, inpatient."},"cycle_length_days":28,"default_cycles":1,"sort_order":0,"sources":[{"name":"Kadia T.M. та ін. Venetoclax plus intensive chemotherapy with cladribine, idarubicin, and cytarabine in patients with newly diagnosed acute myeloid leukaemia or high-risk myelodysplastic syndrome: a cohort from a single-centre, single-arm, phase 2 trial. Lancet Haematol. 2021;8(8):e552-e561","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8884174/","version":"рукопис автора в PMC, розділ Procedures","checkedOn":"2026-10-09"},{"name":"EMC SmPC: Leustat injection (cladribine 1 mg/ml), розділи 4.2, 6.6 — розведення в 100–500 мл 0,9 % NaCl","url":"https://www.medicines.org.uk/emc/product/13187/smpc","version":"Date of revision of the text 23/04/2026","checkedOn":"2026-11-20"},{"name":"EMC SmPC: Zavedos 1mg/mL Solution for Injection, розділ 6.6 — у систему з вільно текучим 0,9 % NaCl, обʼєм не вказано","url":"https://www.medicines.org.uk/emc/product/13262/smpc","checkedOn":"2026-11-20"}],"evidence":{"design":{"uk":"Одноцентрове дослідження фази II (MD Anderson) без групи порівняння, окрема когорта з венетоклаксом. Курси по 28 днів, до 6 курсів; у першій ремісії — алогенна трансплантація, якщо можлива.","en":"A single-centre phase II study (MD Anderson) without a comparison group, a separate venetoclax cohort. 28-day courses, up to 6; an allogeneic transplant in first remission where possible."},"population":{"uk":"50 пацієнтів 18–65 років (медіана 48) з уперше діагностованим ГМЛ, змішаним фенотипом або МДС високого ризику.","en":"50 patients aged 18 to 65 (median 48) with newly diagnosed AML, mixed phenotype or high-risk MDS."},"results":{"uk":"Композитна повна ремісія 94%, МЗХ не виявлена у 82%. Річна виживаність без подій 68%, загальна — 85%. Одна смерть під час індукції.","en":"Composite complete remission 94%, undetectable MRD in 82%. One-year event-free survival 68%, overall 85%. One induction death."},"conduct":{"uk":"Перший курс — у стаціонарі. Венетоклакс 400 мг у дні 2–8 без нарощування; при лейкоцитах понад 20×10⁹/л — циторедукція до початку. З азолами: сильні інгібітори CYP3A — венетоклакс 100 мг, помірні — 200 мг. Антибактеріальна, противірусна і протигрибкова профілактика на час нейтропенії. Фебрильна нейтропенія 3+ ступеня у 84%, підвищення АЛТ. При мутації FLT3 у дослідженні додавали мідостаурин (в Україні недоступний) або гілтеритиніб (є у відділенні); дозування в поєднанні з CLIA тут не звірене.","en":"The first course is inpatient. Venetoclax 400 mg on days 2 to 8 without a ramp-up; with leukocytes over 20×10⁹/L, cytoreduction first. With azoles: strong CYP3A inhibitors, venetoclax 100 mg; moderate, 200 mg. Antibacterial, antiviral and antifungal prophylaxis during neutropenia. Grade 3+ febrile neutropenia in 84%, raised ALT. With an FLT3 mutation the study added midostaurin (not available in Ukraine) or gilteritinib (available in the department); its dosing with CLIA is not checked here."},"trial":{"nct":"NCT02115295","phase":"II","randomized":false,"n":50},"settings":["first-line","high-risk"],"verdict":"option","appraisal":[{"publication":"Kadia T.M. та ін. Lancet Haematol. 2021;8(8):e552-e561","pmid":"34329576","level":{"scale":"oxford-cebm-2011","value":"4","notes":{"uk":"Дослідження без рандомізованої групи порівняння: усі пацієнти отримували ту саму схему. За оксфордською шкалою це 4-й рівень.","en":"A study without a randomised comparison group: every patient had the same regimen. That is level 4 on the Oxford scale."}},"publication_types":["Clinical Trial, Phase II","Journal Article"],"journal":{"name":"The Lancet Haematology","issn":"2352-3026","medline_indexed":true},"sources":[{"name":"Запис статті в PubMed (типи публікації за класифікацією NLM)","url":"https://pubmed.ncbi.nlm.nih.gov/34329576/","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Каталог NLM, запис журналу «The Lancet Haematology» (статус індексації)","url":"https://www.ncbi.nlm.nih.gov/nlmcatalog/101643584","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Oxford Centre for Evidence-Based Medicine, рівні доказовості 2011","url":"https://www.cebm.ox.ac.uk/resources/levels-of-evidence/ocebm-levels-of-evidence","version":"редакція 2011 року","checkedOn":"2026-10-09"}]}]},"reference":null,"course":{"id":"clia-ven","title":{"uk":"CLIA-Ven","en":"CLIA-Ven"},"phase":{"uk":"індукція","en":"induction"},"order":1,"cycles":null},"print_forms":{"version":1,"forms":[]}},{"id":"dac-induction","short_name":"DAC","name":{"uk":"DAC (даунорубіцин + цитарабін + кладрибін), індукція","en":"DAC (daunorubicin, cytarabine and cladribine), induction"},"description":{"uk":"Індукція вперше діагностованого ГМЛ у придатних до інтенсивної терапії. Один курс; оцінка кісткового мозку на 14-й день.","en":"Induction of newly diagnosed AML in patients fit for intensive therapy. One course; marrow assessment on day 14."},"cycle_length_days":28,"default_cycles":1,"sort_order":0,"sources":[{"name":"Holowiecki J. та ін. Cladribine, but not fludarabine, added to daunorubicin and cytarabine during induction prolongs survival of patients with acute myeloid leukemia: a multicenter, randomized phase III study. J Clin Oncol. 2012;30(20):2441-2448","url":"https://pubmed.ncbi.nlm.nih.gov/22508825/","version":"резюме; фаза III, 652 пацієнти","checkedOn":"2026-10-09"},{"name":"Holowiecki J. та ін. Addition of cladribine to daunorubicin and cytarabine increases complete remission rate after a single course of induction treatment in acute myeloid leukemia. Leukemia. 2004;18(5):989-997","url":"https://pubmed.ncbi.nlm.nih.gov/14999298/","version":"резюме; фаза III, 400 пацієнтів (дози DAC-7)","checkedOn":"2026-10-09"},{"name":"Pluta A. та ін. Addition of cladribine to the standard induction treatment improves outcomes in a subset of elderly acute myeloid leukemia patients. Am J Hematol. 2017;92(4):359-366","url":"https://pubmed.ncbi.nlm.nih.gov/28103640/","version":"резюме; рандомізована фаза II, 171 пацієнт старше 60 років","checkedOn":"2026-10-09"},{"name":"ClinicalTrials.gov NCT03257241 (PALG: DA-90 проти DAC; порятунок CLAG-M проти FLAG-IDA), опис груп лікування","url":"https://clinicaltrials.gov/study/NCT03257241","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"NSSG Oxford Haematology, ML.6 DA (daunorubicin + cytarabine) — даунорубіцин у 250 мл 0,9 % NaCl за 1 год","url":"https://nssg.oxford-haematology.org.uk/myeloid/protocols/ML-6-da.pdf","version":"червень 2025","checkedOn":"2026-11-20"},{"name":"EMC SmPC: Leustat injection (cladribine 1 mg/ml), розділи 4.2, 6.6 — розведення в 100–500 мл 0,9 % NaCl","url":"https://www.medicines.org.uk/emc/product/13187/smpc","version":"Date of revision of the text 23/04/2026","checkedOn":"2026-11-20"}],"evidence":{"design":{"uk":"Два рандомізовані дослідження фази III Польської групи з лейкозів дорослих (PALG): DAC проти DA (2004, 400 пацієнтів) і DA проти DAC проти DAF (2012, 652 пацієнти). Подальше лікування в групах однакове.","en":"Two randomised phase III trials of the Polish Adult Leukemia Group (PALG): DAC against DA (2004, 400 patients) and DA against DAC against DAF (2012, 652 patients). Post-remission treatment was the same across arms."},"population":{"uk":"Нелікований ГМЛ у дорослих до 60 років (медіана віку 45–47). Окреме рандомізоване дослідження фази II — 171 пацієнт старше 60 років.","en":"Untreated AML in adults up to 60 (median age 45 to 47). A separate randomised phase II trial enrolled 171 patients over 60."},"results":{"uk":"2012: повна ремісія 67,5% проти 56% з DA (p=0,01) за рахунок меншої резистентності (21% проти 34%); трирічна загальна виживаність 45% проти 33% (p=0,02). Найбільша перевага — від 50 років, при лейкоцитах понад 50×10⁹/л і несприятливому каріотипі. 2004: повна ремісія після одного курсу 64% проти 47%, госпіталізація на 7 днів коротша. Старше 60 років загальна виживаність не покращилася (8,6 проти 9,1 місяця), але у віці 60–65 повна ремісія 51% проти 29%.","en":"2012: complete remission 67.5% against 56% with DA (p=0.01) through less resistant disease (21% against 34%); three-year overall survival 45% against 33% (p=0.02). The greatest benefit at 50 or over, with leukocytes over 50×10⁹/L and an adverse karyotype. 2004: complete remission after one course 64% against 47%, a hospital stay 7 days shorter. Over 60 overall survival did not improve (8.6 against 9.1 months), but at 60 to 65 complete remission was 51% against 29%."},"conduct":{"uk":"Токсичність не відрізнялася від DA ні в молодших, ні в старших. Кладрибін вводять за 2 години перед цитарабіном. У пацієнтів, які отримали DAC в індукції, порятунок CLAG дав лише 10% повних ремісій (проти 58% після DA).","en":"Toxicity did not differ from DA in younger or older patients. Cladribine is infused over 2 hours before cytarabine. In patients induced with DAC, CLAG salvage gave only 10% complete remissions (against 58% after DA)."},"trial":{"acronym":"PALG DAC","phase":"III","randomized":true,"n":652,"comparator":"DA","primary_met":true},"settings":["first-line"],"verdict":"option","appraisal":[{"publication":"Holowiecki J. та ін. J Clin Oncol. 2012;30(20):2441-2448","pmid":"22508825","level":{"scale":"oxford-cebm-2011","value":"2","notes":{"uk":"Рандомізоване дослідження: пацієнтів розподіляли між схемами випадково. За оксфордською шкалою це 2-й рівень.","en":"A randomised trial: patients were allocated to the regimens at random. That is level 2 on the Oxford scale."}},"publication_types":["Clinical Trial, Phase III","Journal Article","Multicenter Study","Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"journal":{"name":"Journal of Clinical Oncology","issn":"0732-183X","medline_indexed":true},"sources":[{"name":"Запис статті в PubMed (типи публікації за класифікацією NLM)","url":"https://pubmed.ncbi.nlm.nih.gov/22508825/","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Каталог NLM, запис журналу «Journal of Clinical Oncology» (статус індексації)","url":"https://www.ncbi.nlm.nih.gov/nlmcatalog/8309333","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Oxford Centre for Evidence-Based Medicine, рівні доказовості 2011","url":"https://www.cebm.ox.ac.uk/resources/levels-of-evidence/ocebm-levels-of-evidence","version":"редакція 2011 року","checkedOn":"2026-10-09"}]},{"publication":"Holowiecki J. та ін. Leukemia. 2004;18(5):989-997","pmid":"14999298","level":{"scale":"oxford-cebm-2011","value":"2","notes":{"uk":"Рандомізоване дослідження: пацієнтів розподіляли між схемами випадково. За оксфордською шкалою це 2-й рівень.","en":"A randomised trial: patients were allocated to the regimens at random. That is level 2 on the Oxford scale."}},"publication_types":["Clinical Trial","Clinical Trial, Phase III","Journal Article","Multicenter Study","Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"journal":{"name":"Leukemia","issn":"0887-6924","medline_indexed":true},"sources":[{"name":"Запис статті в PubMed (типи публікації за класифікацією NLM)","url":"https://pubmed.ncbi.nlm.nih.gov/14999298/","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Каталог NLM, запис журналу «Leukemia» (статус індексації)","url":"https://www.ncbi.nlm.nih.gov/nlmcatalog/8704895","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Oxford Centre for Evidence-Based Medicine, рівні доказовості 2011","url":"https://www.cebm.ox.ac.uk/resources/levels-of-evidence/ocebm-levels-of-evidence","version":"редакція 2011 року","checkedOn":"2026-10-09"}]},{"publication":"Pluta A. та ін. Am J Hematol. 2017;92(4):359-366","pmid":"28103640","level":{"scale":"oxford-cebm-2011","value":"2","notes":{"uk":"Рандомізоване дослідження: пацієнтів розподіляли між схемами випадково. За оксфордською шкалою це 2-й рівень.","en":"A randomised trial: patients were allocated to the regimens at random. That is level 2 on the Oxford scale."}},"publication_types":["Clinical Trial, Phase II","Journal Article","Randomized Controlled Trial"],"journal":{"name":"American Journal of Hematology","issn":"0361-8609","medline_indexed":true},"sources":[{"name":"Запис статті в PubMed (типи публікації за класифікацією NLM)","url":"https://pubmed.ncbi.nlm.nih.gov/28103640/","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Каталог NLM, запис журналу «American Journal of Hematology» (статус індексації)","url":"https://www.ncbi.nlm.nih.gov/nlmcatalog/7610369","version":"запис на дату звірки","checkedOn":"2026-10-09"},{"name":"Oxford Centre for Evidence-Based Medicine, рівні доказовості 2011","url":"https://www.cebm.ox.ac.uk/resources/levels-of-evidence/ocebm-levels-of-evidence","version":"редакція 2011 року","checkedOn":"2026-10-09"}]}]},"reference":null,"course":null,"print_forms":{"version":1,"forms":[]}},{"id":"igev","short_name":"IGEV","name":{"uk":"IGEV (іфосфамід + гемцитабін + вінорелбін + преднізолон)","en":"IGEV (ifosfamide, gemcitabine, vinorelbine, prednisolone)"},"description":{"uk":"Іфосфамід із месною дні 1-4, гемцитабін у дні 1 і 4, вінорелбін у день 1, преднізолон дні 1-4. Цикл 21 день, зазвичай 4 цикли. Сальвадж-схема при рефрактерній або рецидивній лімфомі Ходжкіна; добре мобілізує стовбурові клітини, тому її часто беруть перед аутологічною трансплантацією. Г-КСФ після циклу — за протоколом відділення.","en":"Ifosfamide with mesna on days 1-4, gemcitabine on days 1 and 4, vinorelbine on day 1, prednisolone on days 1-4. A 21-day cycle, usually four cycles. Salvage for refractory or relapsed Hodgkin lymphoma; it mobilises stem cells well, so it is often chosen before autologous transplantation. G-CSF after the cycle follows local policy."},"cycle_length_days":21,"default_cycles":4,"sort_order":0,"sources":[{"name":"Santoro A. та ін. Ifosfamide, gemcitabine, and vinorelbine: a new induction regimen for refractory and relapsed Hodgkin's lymphoma. Haematologica. 2007;92(1):35-41","url":"https://pubmed.ncbi.nlm.nih.gov/17229633/","version":"дослідження фази II, 91 пацієнт","checkedOn":"2026-10-03"},{"name":"eviQ: IGEV (протокол 4253)","url":"https://www.eviq.org.au/haematology/lymphoma/hodgkin-lymphoma/4253-hodgkin-lymphoma-igev-ifosfamide-gemcitabine","version":"перевірено 2026-10-04","checkedOn":"2026-10-04"},{"name":"eviQ: IGEV (протокол 4253) — месна 2000 мг/м² у 1000 мл 0,9 % NaCl за 2 год разом з іфосфамідом","url":"https://www.eviq.org.au/haematology/lymphoma/hodgkin-lymphoma/4253-hodgkin-lymphoma-igev-ifosfamide-gemcitabine","version":"перевірено 2026-11-20","checkedOn":"2026-11-20"}],"evidence":{"design":{"uk":"Проспективне дослідження однієї групи без рандомізації. Дози фіксовані, цикл 21 день, відповідь оцінювали після 4 циклів, далі — збір стовбурових клітин і високодозова терапія.","en":"A prospective single-arm study without randomisation. Fixed doses, a 21-day cycle, response assessed after four cycles, then stem cell collection and high-dose therapy."},"population":{"uk":"91 пацієнт із рефрактерною або рецидивною лімфомою Ходжкіна.","en":"91 patients with refractory or relapsed Hodgkin lymphoma."},"results":{"uk":"Повна ремісія у 53,8%, часткова — у 27,5%; загальна відповідь 81,3%. Прогноз залежав від відповіді на попередню хіміотерапію та від ураження трьох і більше ділянок. Достатню мобілізацію стовбурових клітин отримали 98,7% пацієнтів.","en":"Complete remission in 53.8% and partial response in 27.5%, an overall response of 81.3%. Response to prior chemotherapy and involvement of three or more sites predicted the outcome. Adequate stem cell mobilisation was achieved in 98.7%."},"conduct":{"uk":"Токсичність була керованою: затримок циклів і зниження доз майже не знадобилося. Іфосфамід вводять на тлі гіпергідратації 2000 мл фізіологічного розчину й під прикриттям месни — без них ризикують геморагічним циститом та енцефалопатією.","en":"Toxicity was manageable, with few delays or dose reductions. Ifosfamide is given with 2000 mL saline hyperhydration and mesna cover; without them the risks are haemorrhagic cystitis and encephalopathy."},"settings":["relapse","refractory","pre-transplant"],"verdict":"option","appraisal":[{"publication":"Santoro A. та ін. Haematologica. 2007;92(1):35-41","pmid":"17229633","level":{"scale":"oxford-cebm-2011","value":"4","notes":{"uk":"Усі пацієнти отримували ту саму схему, групи порівняння не було. За оксфордською шкалою це 4-й рівень.","en":"Every patient had the same regimen and there was no comparison group. That is level 4 on the Oxford scale."}},"publication_types":["Clinical Trial","Journal Article"],"journal":{"name":"Haematologica","issn":"1592-8721","medline_indexed":true},"sources":[{"name":"Запис статті в PubMed (типи публікації за класифікацією NLM)","url":"https://pubmed.ncbi.nlm.nih.gov/17229633/","version":"запис на дату звірки","checkedOn":"2026-10-03"},{"name":"Каталог NLM, запис журналу «Haematologica» (статус індексації)","url":"https://www.ncbi.nlm.nih.gov/nlmcatalog/0417435","version":"запис на дату звірки","checkedOn":"2026-10-03"},{"name":"Oxford Centre for Evidence-Based Medicine, рівні доказовості 2011","url":"https://www.cebm.ox.ac.uk/resources/levels-of-evidence/ocebm-levels-of-evidence","version":"редакція 2011 року","checkedOn":"2026-10-03"}]}]},"reference":null,"course":null,"print_forms":{"version":1,"forms":[]}},{"id":"pivekimab-bpdcn","short_name":"Півекімаб","name":{"uk":"Півекімаб суніріне (БПДКН)","en":"Pivekimab sunirine (BPDCN)"},"description":{"uk":"БПДКН, CD123-спрямована терапія: 0,045 мг/кг в/в за 30 хв у день 1 циклу 21 день до прогресування чи неприйнятної токсичності. Виключення: ураження ЦНС, СОС в анамнезі, капілярний витік 4 ст., некардіогенний набряк 4 ст.","en":"BPDCN, CD123-directed: 0.045 mg/kg IV over 30 min on day 1 of a 21-day cycle until progression or unacceptable toxicity. Exclusions: CNS involvement, prior SOS, grade 4 capillary leak, grade 4 non-cardiac oedema."},"cycle_length_days":21,"default_cycles":6,"sort_order":0,"sources":[{"name":"NCCN Guidelines: Blastic Plasmacytoid Dendritic Cell Neoplasm (в одному документі з AML), BPDCN-2 (дози й дні як факти; текст не копіювався)","url":"https://www.nccn.org/guidelines/guidelines-detail?category=1&id=1411","version":"5.2026 від 15.07.2026","checkedOn":"2026-10-22"},{"name":"FDA label: DECNUPAZ (pivekimab sunirine-pvzy), розділ 2.5 Instructions for Preparation","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=508b6ff8-601d-4901-a7a5-816141134054","checkedOn":"2026-11-20"}],"evidence":null,"reference":null,"course":null,"print_forms":{"version":1,"forms":[]}},{"id":"tagraxofusp-bpdcn","short_name":"Тагракcофусп","name":{"uk":"Тагракcофусп (БПДКН)","en":"Tagraxofusp (BPDCN)"},"description":{"uk":"БПДКН, CD123-спрямована терапія: 12 мкг/кг в/в за 15 хв щодня, дні 1–5 циклу 21 день. Умови старту: альбумін ≥3,2 г/дл, ФВ ЛШ не нижче норми, креатинін ≤1,5 мг/дл, білірубін ≤1,5 мг/дл, АСТ/АЛТ ≤2,5×ВМН, без значущої серцево-судинної хвороби. Перший цикл — стаціонар, спостереження ≥24 год.","en":"BPDCN, CD123-directed: 12 mcg/kg IV over 15 min daily on days 1-5 of a 21-day cycle. Start conditions: albumin 3.2 g/dL or more, LVEF at least the lower limit of normal, creatinine and bilirubin 1.5 mg/dL or less, AST/ALT 2.5 x ULN or less, no clinically significant cardiovascular disease. Cycle 1 as an inpatient, observed at least 24 h."},"cycle_length_days":21,"default_cycles":6,"sort_order":0,"sources":[{"name":"NCCN Guidelines: Blastic Plasmacytoid Dendritic Cell Neoplasm (в одному документі з AML), BPDCN-2, BPDCN-C (дози й дні як факти; текст не копіювався)","url":"https://www.nccn.org/guidelines/guidelines-detail?category=1&id=1411","version":"5.2026 від 15.07.2026","checkedOn":"2026-10-22"},{"name":"FDA label: ELZONRIS (tagraxofusp-erzs), розділ 2.4 Preparation and Administration","url":"https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=80eb1080-fe20-4af0-b2a5-a67999923fa8","checkedOn":"2026-11-20"}],"evidence":null,"reference":null,"course":null,"print_forms":{"version":1,"forms":[]}}]$catalog$::jsonb)
